recipes.code:
{
  "inputs": [
    {
      "id": "notion-token",
      "type": "promptString",
      "description": "Optional Notion internal integration token (enables the Notion connector)",
      "password": true
    }
  ],
  "servers": {
    "ctxfile": {
      "type": "stdio",
      "command": "npx",
      "args": [
        "-y",
        "ctxfile@0.4.0"
      ],
      "env": {
        "NOTION_TOKEN": "${input:notion-token}"
      }
    }
  }
}
